values.content:
=Write a message for this past client.

Reason for outreach: {{ $json.reason }}
Context: {{ $json.context }}
Name: {{ $json.name }}
Notes about them: {{ $json.notes }}
Their purchase date (if any): {{ $json.home_purchase_date }}

parameters.jsCode:
const today = new Date();
const todayMonth = today.getUTCMonth();
const todayDay = today.getUTCDate();
const NINETY_DAYS_MS = 90 * 24 * 60 * 60 * 1000;

const results = [];

for (const item of $input.all()) {
  const c = item.json;

  // Skip leads — they're handled by the Gmail workflows, not nurture
  if (c.relationship_type === 'lead') continue;

  let reason = null;
  let context = '';

  // Check birthday
  if (c.birthday) {
    const bday = new Date(c.birthday);
    if (bday.getUTCMonth() === todayMonth && bday.getUTCDate() === todayDay) {
      reason = 'birthday';
    }
  }

  // Check home anniversary (only if no birthday match)
  if (!reason && c.home_purchase_date) {
    const purchase = new Date(c.home_purchase_date);
    if (purchase.getUTCMonth() === todayMonth && purchase.getUTCDate() === todayDay) {
      const years = today.getUTCFullYear() - purchase.getUTCFullYear();
      if (years > 0) {
        reason = 'anniversary';
        context = `${years} year${years > 1 ? 's' : ''} since they bought their home`;
      }
    }
  }

  // Check stale contact (only if no birthday/anniversary)
  if (!reason && c.last_contacted_at) {
    const lastContact = new Date(c.last_contacted_at);
    const daysSince = (today - lastContact) / (24 * 60 * 60 * 1000);
    if (daysSince >= 90) {
      reason = 'reconnect';
      context = `${Math.floor(daysSince)} days since last contact`;
    }
  }

  if (reason) {
    results.push({
      json: {
        ...c,
        reason: reason,
        context: context
      }
    });
  }
}

return results;

